"""Versioned, server-only editorial content for the learning games.

The browser receives only the current prompt and its answer labels. Correct
answers, score values and the full rotation remain on the server.  IDs are
stable so a session can freeze its selected content even when a later release
adds or retires a scenario.
"""
from __future__ import annotations

CONTENT_VERSION = "2026.10"
LEARNING_SESSION_LENGTH = 6


def _safety(identifier, difficulty, tags, title, scene, question, choices, correct, explanation, principle):
    return {
        "id": identifier, "version": CONTENT_VERSION, "published": True,
        "difficulty": difficulty, "tags": tuple(tags), "title": title,
        "scene": scene, "question": question, "choices": tuple(choices),
        "correct": correct, "explanation": explanation, "principle": principle,
    }


def _mission(identifier, difficulty, tags, title, person, place, scene, choices):
    return {
        "id": identifier, "version": CONTENT_VERSION, "published": True,
        "difficulty": difficulty, "tags": tuple(tags), "title": title,
        "person": person, "place": place, "scene": scene,
        "choices": tuple(choices),
        "correct": max(range(len(choices)), key=lambda index: choices[index][1]),
    }


