SCENARIOS_BY_GAME = {"safety": SAFETY_SCENARIOS, "mission": MISSION_SCENARIOS}


def published_scenarios(game_code: str) -> tuple[dict, ...]:
    return tuple(item for item in SCENARIOS_BY_GAME.get(game_code, ()) if item.get("published"))


def scenario_by_id(game_code: str, identifier: str) -> dict | None:
    return next((item for item in published_scenarios(game_code) if item["id"] == identifier), None)
